// Light by @Shane
// https://www.shadertoy.com/view/XsG3z1
void mainImage(out vec4 fragColor, in vec2 fragCoord){


    // The screen coordinates.
    vec2 uv = fragCoord/iResolution.xy;

    // Read in the blurred pixel value. There's no rule that says you can't read in the
    // value in the "X" channel, but blurred stuff is easier to bump, that's all.
    float c = 1. - texture(iChannel0, uv).y; 
    // Reading in the same at a slightly offsetted position. The difference between
    // "c2" and "c" is used to provide the highlighting.
    float c2 = 1. - texture(iChannel0, uv + .5/iResolution.xy).y;


    // Color the pixel by mixing two colors in a sinusoidal kind of pattern.
    float pattern = -cos(uv.x*1.75*3.14159 - .9)*cos(uv.y*1.5*3.14159 - .75)*.5 + .5;

    // Blue and gold, for an abstract sky over a... wheat field look. Very artsy. :)
    vec3 col = pow(vec3(0.039,0.039,0.043)*c,vec3(1.5, 1, 1));
    col = mix(col, col.zyx, clamp(pattern - .2, 0., 1.) );

    // Extra color variations.
    //vec3 col = mix(vec3(c*1.2, pow(c, 8.), pow(c, 2.)), vec3(c*1.3, pow(c, 2.), pow(c, 10.)), pattern );
	//vec3 col = mix(vec3(c*1.3, c*c, pow(c, 10.)), vec3(c*c*c, c*sqrt(c), c), pattern );

    // Adding the highlighting. Not as nice as proper bump mapping, but still pretty effective.
    col += vec3(0.165,0.957,0.941)*max(c2*c2 - c*c, 0.)*10.;

    // Apply a vignette and increase the brightness for that fake spotlight effect.
    col *= pow( 18.0*uv.x*uv.y*(1. - uv.x)*(1. - uv.y) ,1.125)*.615;

    // Fade in for the first few seconds.
    col *= smoothstep(0., 1., iTime/5.);

    // Rough gamma correction.
    fragColor = vec4(sqrt(min(col, 1.)), 1); 


}

void mainImage(out vec4 O, in vec2 I) 
{
    vec2 uv = I / iResolution.xy;

    vec4 state = grayScott(I, iChannel0, iResolution.xy, iTime, iFrame);
    float u = state.x;
    float v = state.y;

    // 2) Moving circle center (goes up and down)
    float speed = 1.0;
    float t = mod(iTime * speed, 4.0); 

    vec2 A = vec2(0.5, 0.9);  // top-left
    vec2 B = vec2(0.3, 0.7);  // bottom center
    vec2 C = vec2(0.5, 0.5);  // top-right

    vec2 k11;
    if (t < 2.0) {
        // First half: bottom-left to top (left side of V)
        float progress = t / 2.0;
        k11 = mix(A, B, progress);
    } else {
        // Second half: top to bottom-right (right side of V)
        float progress = (t - 2.0) / 2.0;
        k11 = mix(B, C, progress);
    }

    float t2 = mod(iTime * speed, 6.0);
    vec2 A1 = vec2(0.6, 0.9);      // top of left side
    vec2 B1 = vec2(0.6, 0.6);   // bottom left corner
    vec2 C1 = vec2(0.8, 0.6); // bottom right corner
    vec2 D1 = vec2(0.8, 0.9);    // top of right side

    vec2 u1;
    if (t2 < 2.0) {
        // Down the left side
        float progress = t2 / 2.0;
        u1 = mix(A1, B1, progress);
    } else if (t2 < 4.0) {
        // Across the bottom
        float progress = (t2 - 2.0) / 2.0;
        u1 = mix(B1, C1, progress);
    } else {
        // Up the right side
        float progress = (t2 - 4.0) / 2.0;
        u1 = mix(C1, D1, progress);
    }

    vec2 A2 = vec2(0.6, 0.5);  // top-left
    vec2 B2 = vec2(0.8, 0.3);  // bottom center
    vec2 C2 = vec2(0.6, 0.1);  // top-right

    vec2 k22;
    if (t < 2.0) {
        // First half: bottom-left to top (left side of V)
        float progress = t / 2.0;
        k22 = mix(A2, B2, progress);
    } else {
        // Second half: top to bottom-right (right side of V)
        float progress = (t - 2.0) / 2.0;
        k22 = mix(B2, C2, progress);
    }

    vec2 k1 = vec2(0.3, 0.7 + 0.2 * sin(iTime * speed));
    //vec2 u1 = vec2(0.7, 0.7 + 0.2 * sin(iTime * speed));
    vec2 o1 = vec2(0.4 + 0.12 * cos(iTime * speed), 0.25 + 0.16 * sin(iTime * speed));
    vec2 k2 = vec2(0.8, 0.3 + 0.2 * sin(iTime * speed));

    float radius = 0.015;
    float d1 = length(uv - k1); float d11 = length(uv - k11);
    float d2 = length(uv - u1);

    float d3 = length(uv - k2);float d33 = length(uv - k22);
    float d4 = length(uv - o1);

    float disk1 = smoothstep(radius, radius - 0.01, d1);float disk11 = smoothstep(radius, radius - 0.01, d11); 
    float disk2 = smoothstep(radius, radius - 0.01, d2);
    float disk3 = smoothstep(radius, radius - 0.01, d3);float disk33 = smoothstep(radius, radius - 0.01, d33); 
    float disk4 = smoothstep(radius, radius - 0.01, d4);

    // 3) Mouse seeding
    if (iFrame > 9 && length(iMouse.xy - I) < 10.0) {
        u = 0.25;
        v = 0.5;
    }

    if (iFrame > 9) {
        // you can tune these values
        float uTarget = 0.25;
        float vTarget = 0.8;

        u -= disk1 * 0.05; v += disk1 * 0.05;u -= disk11 * 0.05; v += disk11 * 0.05;
        u -= disk2 * 0.05; v += disk2 * 0.05;
        u -= disk3 * 0.05; v += disk3 * 0.05;u -= disk33 * 0.05; v += disk33 * 0.05;
        u -= disk4 * 0.05; v += disk4 * 0.05;
    }

    O = vec4(clamp(u, 0.0, 1.0), clamp(v, 0.0, 1.0), 0.0, 0.0);
}

// Noise 
vec3 hash33(in vec2 p) { 
    float n = sin(dot(p, vec2(41, 289)));    
    return fract(vec3(2097152, 262144, 32768) * n); 
}

// Discrete Laplacian operator: ∇²u ≈ (neighbors - 4×center)
// Measures local curvature of the concentration field
vec2 laplacian(in vec2 uv, vec2 px, sampler2D ch) 
{   
    vec2 c = texture(ch, uv).xy;                    // Center

    vec2 r = texture(ch, uv + vec2(px.x, 0)).xy;    // Right
    vec2 l = texture(ch, uv - vec2(px.x, 0)).xy;    // Left
    vec2 u = texture(ch, uv + vec2(0, px.y)).xy;    // Up
    vec2 d = texture(ch, uv - vec2(0, px.y)).xy;    // Down

    return (r + l + u + d - 4.0 * c);
}

vec2 laplacianAniso(in vec2 uv, vec2 px, sampler2D ch)
{
    vec2 c = texture(ch, uv).xy;

    // 1) Define a vector field: here, tangent to circles around center
    vec2 p = uv - 0.5;
    float r = max(length(p), 1e-3);
    vec2 t = normalize(vec2(-p.y, p.x));   // tangent direction
    vec2 n = vec2(-t.y, t.x);              // normal direction

    float h = px.x;                         // step size (assuming near-square res)
    vec2 tstep = t * h;
    vec2 nstep = n * h;

    // 2) Sample along tangent and normal
    vec2 utp = texture(ch, uv + tstep).xy;
    vec2 utm = texture(ch, uv - tstep).xy;
    vec2 unp = texture(ch, uv + nstep).xy;
    vec2 unm = texture(ch, uv - nstep).xy;

    vec2 u_tt = utp + utm - 2.0 * c;       // second deriv along t
    vec2 u_nn = unp + unm - 2.0 * c;       // second deriv along n

    // 3) Weights: more diffusion along t than n
    float a = 2.;   // along flow
    float b = 0.2;   // across flow

    return a * u_tt + b * u_nn;
}

// ═══════════════════════════════════════════════════════════════════════════
// Gray-Scott Reaction-Diffusion System
// ═══════════════════════════════════════════════════════════════════════════
// A mathematical model of two chemicals U and V that react and diffuse
// Creates self-organizing patterns: spots, stripes, spirals, chaos
//
// The system equations:
//   ∂u/∂t = Du∇²u - uv² + f(1-u)
//   ∂v/∂t = Dv∇²v + uv² - (k+f)v
//
// Where:
//   u, v     = concentrations of chemicals A and B
//   Du, Dv   = diffusion rates (how fast chemicals spread)
//   f        = feed rate (replenishment of u)
//   k        = kill rate (removal of v)
//   uv²      = reaction term (v is produced by consuming u)
// ═══════════════════════════════════════════════════════════════════════════

vec4 grayScott(in vec2 I, sampler2D ch, vec2 res, float time, int frame) 
{
    vec2 uv = I / res;
    vec2 px = 1.0 / res;

    // Current chemical concentrations
    float u = texture(ch, uv).x;  // Chemical A
    float v = texture(ch, uv).y;  // Chemical B

    // Calculate spatial derivatives (laplacian)
    vec2 lapIso  = laplacian(uv, px, ch);
    vec2 lapAniso = laplacianAniso(uv, px, ch);

    // Blend to keep it stable but clearly anisotropic
    vec2 lap = mix(lapIso, lapAniso, 0.7);

    // ───────────────────────────────────────────────────────────────────────
    // Parameters (tune these to create different patterns)
    // ───────────────────────────────────────────────────────────────────────
    float Du = 0.2097;      // Diffusion rate for U (faster)
    float Dv = 0.075;       // Diffusion rate for V (slower)
    float f  = 0.06;        // Feed rate (adds U)
    float k  = 0.065;       // Kill rate (removes V)

    // ───────────────────────────────────────────────────────────────────────
    // The reaction term: uv²
    // Chemical V catalyzes its own production by consuming U
    // ───────────────────────────────────────────────────────────────────────
    float uvv = u * v * v;

    // Chemical U (substrate):
    float newU = u 
               + Du * lap.x       // Du ∇²u
               - uvv              // - uv²
               + f * (1.0 - u);   // + f(1-u)

    // Chemical V (autocatalyst):
    float newV = v 
               + Dv * lap.y       // Dv ∇²v
               + uvv              // + uv²
               - (k + f) * v;     // - (k+f)v

    // ───────────────────────────────────────────────────────────────────────
    // Stochastic perturbation
    // ───────────────────────────────────────────────────────────────────────
    vec3 noise = hash33(uv + vec2(53, 43) * time);
    newU += (noise.x - 0.5) * 0.0001;
    newV += (noise.y - 0.5) * 0.0001;

    // ───────────────────────────────────────────────────────────────────────
    // Init
    // ───────────────────────────────────────────────────────────────────────
    if(frame < 10)
    {
        vec2 center = uv - 0.5;

        float dist = smoothstep(0.43, 0.3, length(center) - 0.5);
        float spot = smoothstep(0.15, 0.1, dist);

        return vec4(1.0, spot * 0.5 + noise.z * 0.05, 0.0, 0.0);
    }
    else 
    {
        return vec4(clamp(newU, 0., 1.), clamp(newV, 0., 1.), 0.0, 0.0);
    }
}

void mainImage(out vec4 O, in vec2 I) 
{
    O = grayScott(I, iChannel0, iResolution.xy, iTime, iFrame);

    // Interactive seeding - click to add chemical V
    bool mouseActive = length(iMouse.xy - I) < 10.0;
    if(mouseActive && iFrame > 9) {
        O = vec4(0.25, 0.5, 0.0, 0.0);  // Seed reaction at cursor
    }
}

